package android.graphics; public class LinearGradient extends Shader { public LinearGradient(float x0,float y0,float x1,float y1,int[] colors,float[] positions,TileMode mode){if(colors.length>0)color=colors[0];} public LinearGradient(float x0,float y0,float x1,float y1,int a,int b,TileMode mode){color=a;} }